	//  ┌──────────────┬──────────┬──────────┬───────────┬────────┐
	//  │ 31 ────── 24 │ 23 ── 16 │    15    │ 14 ──── 8 │ 7 ── 0 │
	//  ├──────────────┼──────────┼──────────┼───────────┼────────┤
	//  │ reserved[^1] │ errno    │ shutdown │ initlevel │ reason │
	//  └──────────────┴──────────┴──────────┴───────────┴────────┘
	//  ```
